});

frappe.ui.form.on("Purchase Order", {
    custom_approver(frm) {
        if (!frm.doc.custom_approver) {
            frm.clear_table("custom_po_request_approver");
            frm.refresh_field("custom_po_request_approver");
            return;
        }

        frappe.call({
            method: "get_reviewer_managers",
            args: {
                custom_approver: frm.doc.custom_approver
            },
            callback: function (r) {
                frm.clear_table("custom_po_request_approver");

                if (!r.message || r.message.length === 0) {
                    frm.refresh_field("custom_po_request_approver");
                    return;
                }

                r.message.forEach((emp, idx) => {
                    let row = frm.add_child("custom_po_request_approver");
                    row.level = idx + 1;
                    row.approver = emp;
                });

                frm.refresh_field("custom_po_request_approver");
            }
        });
    }
});

