frappe.ui.form.on('Payment Entry', {
    onload: function(frm) {
        //fetch posting date if missing
        if (!frm.doc.posting_date) {
            frm.set_value('posting_date', frappe.datetime.get_today());
        }

        // get posting date into cheque/reference date
        if (!frm.doc.reference_date && frm.doc.posting_date) {
            frm.set_value('reference_date', frm.doc.posting_date);
        }


        setTimeout(() => {
            if (!frm.doc.reference_date && frm.doc.posting_date) {
                frm.set_value('reference_date', frm.doc.posting_date);
            }
        }, 150);
    },

    //when change the posting date
    posting_date: function(frm) {
        if (frm.doc.posting_date) {
            frm.set_value('reference_date', frm.doc.posting_date);
        }
    },

    refresh: function(frm) {
        if (frm.is_new() && !frm.doc.reference_date && frm.doc.posting_date) {
            frm.set_value('reference_date', frm.doc.posting_date);
        }
    }
});

frappe.ui.form.on('Material Request', {
    refresh(frm) {
        // Auto-fill custom_creator_employee if empty
        if (!frm.doc.custom_creator_employee && frappe.session.user) {
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Employee",
                    filters: { user_id: frappe.session.user },
                    fieldname: ["name"]
                },
                callback: function(r) {
                    if (r.message && r.message.name) {
                        frm.set_value("custom_creator_employee", r.message.name);
                        // build approver chain so user sees approvers immediately
                        frm.trigger("set_approvers");
                    }
                }
            });
        }
    },

    // When the creator_employee field changes, rebuild chain
    custom_creator_employee(frm) {
        frm.trigger("set_approvers");
    },

    // Build chain client-side by repeatedly fetching reports_to from Employee
    async set_approvers(frm) {
        if (!frm.doc.custom_creator_employee) return;

        // helper: get reports_to for an employee
        const getReportsTo = (employee) => {
            return frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Employee",
                    filters: { name: employee },
                    fieldname: ["reports_to"]
                }
            });
        };

        let chain = [];
        let visited = new Set();
        let current = frm.doc.custom_creator_employee;

        // Prevent infinite loops by limiting iterations (safety)
        const MAX_LEVELS = 10;

        for (let i = 0; i < MAX_LEVELS; i++) {
            if (!current || visited.has(current)) break;
            visited.add(current);

            // fetch reports_to for current
            try {
                let res = await getReportsTo(current);
                let reports_to = (res && res.message) ? res.message.reports_to : null;
                if (!reports_to) break;
                chain.push(reports_to);
                current = reports_to;
            } catch (err) {
                console.error("Error fetching reports_to:", err);
                break;
            }
        }

        // Fill the child table approval_levels
        frm.clear_table("custom_approval_levels");

        chain.forEach(function(emp_name, idx) {
            let row = frm.add_child("custom_approval_levels");
            row.level = idx + 1;
            row.approver = emp_name;
        });

        frm.refresh_field("custom_approval_levels");
    }
});

