                    year_start_date: ["<=", frm.doc.posting_date],
                    year_end_date: [">=", frm.doc.posting_date]
                },
                fieldname: "name"
            },
            callback: function(r) {
                if (r.message) {
                    frm.set_value("custom_fiscal_year", r.message.name);
                } else {
                    frm.set_value("custom_fiscal_year", "Not Found");
                }
            }
        });
    }
}


function set_naming_series_based_on_return(frm) {
    if (frm.doc.is_return == 1) {
        frm.set_value('naming_series', '.{custom_abbr}.RTN-.######.-.{custom_fiscal_year}');
    } else {
        frm.set_value('naming_series', '.{custom_abbr}.######.-.{custom_fiscal_year}');
    }
}
